import{_ as i,l as n,o as a,c,v as o,p as l,x as r,d,i as s,S as p}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"源码编码与 Unicode 词法","description":"","frontmatter":{"title":"源码编码与 Unicode 词法","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/source-encoding-lexing.md","filePath":"cs/source-encoding-lexing.md","lastUpdated":1789023840000}'),h={name:"cs/source-encoding-lexing.md"};function u(_,e,A,E,m,f){const t=n("Mermaid");return a(),c("div",null,[e[1]||(e[1]=o('<h1 id="源码编码与-unicode-词法" tabindex="-1">源码编码与 Unicode 词法 <a class="header-anchor" href="#源码编码与-unicode-词法" aria-label="Permalink to &quot;源码编码与 Unicode 词法&quot;">​</a></h1><div class="epigraph"><p>词法的字母表不是「字节」。规范化、BOM、同形字与标识符字符类决定两个源文件是不是同一个程序。</p><footer>—— 据 Unicode 标准标识符附录；ISO C/C++ 通用字符名；Peyton Jones 等对 Haskell 词法的讨论整理</footer></div><p>上一课<a href="/cs/c-preprocessor">C 预处理器</a>假定已经有了「记号」。更早的翻译阶段是<strong>物理编码</strong>：UTF-8、续行、三字符组（历史）、通用字符名 <code>\\uXXXX</code>。主干<a href="/cs/regex-lexer">正则与词法</a>用 ASCII 讲最长匹配。缺口是<strong>字母表真正是什么</strong>，以及 lex 规则在 Unicode 下如何仍保持确定扫描。本课收束前端进阶课序，不重写 UTF-8 编解码课的全部位模式。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>同一标识符可有预组合与分解形式（NFC/NFD）。语言必须规定：先规范化再比较，还是按字节比较。BOM 在文件头不是标识符。零宽字符可把两个看起来一样的名字拆开——工具链要不要拒。缺口是<strong>词法字母表与等价</strong>，不是再画 DFA 子集构造。</p><p>flex 默认字节；要认 Unicode 标识符需字符类与编码转换，否则正则 <code>.</code> 的意义漂在 UTF-8 续字节上。</p><h3 id="同形字不是正则冲突" tabindex="-1">同形字不是正则冲突 <a class="header-anchor" href="#同形字不是正则冲突" aria-label="Permalink to &quot;同形字不是正则冲突&quot;">​</a></h3><p><code>latin a</code> 与 <code>cyrillic а</code> 是不同码点，DFA 可以区分。人不可区分。这是诊断与安全策略，不是 NFA 等价问题。不要用「加一条正则」假装解决。</p><p><span class="marginnote">Unicode UAX #31（标识符）。C++ 的 UCN 与 raw string 改变词法最长匹配。本课不进入显示层 Bidirectional 全部算法，只点名源码欺骗（Trojan Source）是词法+渲染问题。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>规定源编码（或探测 UTF-8）。解码为码点流，再跑词法 DFA。标识符：<code>XID_Start</code>/<code>XID_Continue</code> 或语言自己的表。字符串字面量：转义、原始字符串、换行规则与 lex 起始条件（<a href="/cs/lex-flex">lex</a>）对齐。</p>',11)),(a(),l(p,null,{default:r(()=>[s(t,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20BYTES%5B%22%E5%AD%97%E8%8A%82%22%5D%20--%3E%20DEC%5B%22%E8%A7%A3%E7%A0%81%E4%B8%BA%E7%A0%81%E7%82%B9%22%5D%0A%20%20DEC%20--%3E%20NORM%5B%22%E5%8F%AF%E9%80%89%E8%A7%84%E8%8C%83%E5%8C%96%22%5D%0A%20%20NORM%20--%3E%20DFA%5B%22%E8%AF%8D%E6%B3%95%20DFA%22%5D%0A%20%20DFA%20--%3E%20TOK%5B%22%E8%AE%B0%E5%8F%B7%22%5D%0A"})]),fallback:r(()=>[...e[0]||(e[0]=[d(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=o('<p>cpp 的 <code>\\u</code> 发生在特定阶段，可能在规范化之前或之后——必须按语言标准钉死，不能凭直觉。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>最长匹配在码点上，不在字节上：多字节字符不能从中切开。错误恢复跳过非法 UTF-8 序列时，行号与列要按语言的列定义（码点或显示宽）报告。</p><p>PEG/Pratt 若直接吃字节，会把 UTF-8 当运算符碎片。前端进阶课序到此：生成器、通用分析、宏、编码——下一单元从无类型 λ 走到类型。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写字体渲染，不规定编辑器是否做 confusable 警告。后课默认：词法字母表是码点（或标准规定的规范化码点）。下一课<a href="/cs/simply-typed-lambda">简单类型 λ</a> 接主干 λ 与类型检查，不再处理 BOM。</p><p>也不把 GBK 与 UTF-8 混用当可移植源。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>词法在码点（及规定的规范化）上跑，不在生字节上。</li><li>Unicode 标识符类与同形字是不同层。</li><li>与 lex/cpp 的阶段顺序必须按语言标准。</li><li>出处：Unicode UAX #31；ISO C/C++ 词法；对照 Thompson/龙书正则词法。</li></ul>',9))])}const D=i(h,[["render",u]]);export{T as __pageData,D as default};
